import type { HTMLAttributes } from 'react';
import { borderProps, type BorderRole } from './Border';

export function Card({ className = '', borderRole, style, ...props }: HTMLAttributes<HTMLDivElement> & { borderRole?: BorderRole }) {
  const decoration = borderProps(borderRole ?? (props.role === 'alert' ? 'danger' : undefined));
  return <div className={`ui-card ${className}`} {...decoration} {...props} style={decoration.style ? { ...decoration.style, ...style } : style} />;
}
